questions.solution:
type Book = {
  title: string;
  cents: number;
};

function priceLabel(book: Book): string {
  return `${book.title}: $${(book.cents / 100).toFixed(2)}`;
}

const book: Book = { title: "TypeScript Basics", cents: 1250 };
console.log(priceLabel(book));
